import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__device__ __forceinline__ float warp_reduce_sum_f32(float val) {
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(mask, val, offset);
    }
    return val;
}

extern "C" __global__
void sdp_fwd_kernel(const __half* __restrict__ Q,
                    const __half* __restrict__ K,
                    const __half* __restrict__ V,
                    __half* __restrict__ Out,
                    int B, int H, int S, int D,
                    float scale)
{
    // Grid mapping:
    // blockIdx.z -> batch index (b)
    // blockIdx.y -> head index (h)
    // blockIdx.x -> query index (qi)
    int b = blockIdx.z;
    int h = blockIdx.y;
    int qi = blockIdx.x;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    // Shared memory layout:
    // [0 .. D-1]            -> q_sh (float)
    // [D .. 2*D-1]          -> acc_v_sh (float)
    extern __shared__ float smem[];
    float* q_sh = smem;
    float* acc_v_sh = q_sh + D;
    int nwarps = (nthreads + 31) >> 5;
    float* redbuf = acc_v_sh + D;
    float* scalars = redbuf + nwarps; // [0]=alpha, [1]=expv
    float* lmem = scalars + 2;        // running l
    float* mmem = lmem + 1;           // running m
    // Compute base row offset (in rows of length D) for (b,h)
    size_t bh_base_rows = ((size_t)b * (size_t)H + (size_t)h) * (size_t)S;
    const __half* q_row = Q + (bh_base_rows + (size_t)qi) * (size_t)D;
    __half* out_row = Out + (bh_base_rows + (size_t)qi) * (size_t)D;
    // Preload Q[qi, :] into shared memory and init shared accumulators
    int D2 = D >> 1;
    const __half2* qh2 = reinterpret_cast<const __half2*>(q_row);
    for (int i = tid; i < D2; i += nthreads * 2) {
        int i0 = i;
        float2 fq0 = __half22float2(qh2[i0]);
        int d0 = i0 * 2;
        q_sh[d0]     = fq0.x;
        q_sh[d0 + 1] = fq0.y;
        acc_v_sh[d0]     = 0.0f;
        acc_v_sh[d0 + 1] = 0.0f;
        int i1 = i0 + nthreads;
        if (i1 < D2) {
            float2 fq1 = __half22float2(qh2[i1]);
            int d1 = i1 * 2;
            q_sh[d1]     = fq1.x;
            q_sh[d1 + 1] = fq1.y;
            acc_v_sh[d1]     = 0.0f;
            acc_v_sh[d1 + 1] = 0.0f;
        }
    }
    // odd tail of Q and per-thread accumulator for it
    float q_last = 0.0f;
    float acc_last = 0.0f;
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        q_last = __half2float(q_row[last]);
    }
    // Initialize running softmax parameters in shared memory
    if (tid == 0) {
        *mmem = -INFINITY;
        *lmem = 0.0f;
    }
    __syncthreads();
    // Iterate over keys j
    for (int j = 0; j < S; ++j) {
        // Compute dot product s = Q[qi,:] . K[j,:]
        const __half* k_row = K + (bh_base_rows + (size_t)j) * (size_t)D;
        const __half2* kh2 = reinterpret_cast<const __half2*>(k_row);
        float local_sum = 0.0f;
        for (int i = tid; i < D2; i += nthreads * 2) {
            int i0 = i;
            int d0 = i0 * 2;
            float2 fk0 = __half22float2(kh2[i0]);
            local_sum = __fmaf_rn(q_sh[d0],     fk0.x, local_sum);
            local_sum = __fmaf_rn(q_sh[d0 + 1], fk0.y, local_sum);
            int i1 = i0 + nthreads;
            if (i1 < D2) {
                int d1 = i1 * 2;
                float2 fk1 = __half22float2(kh2[i1]);
                local_sum = __fmaf_rn(q_sh[d1],     fk1.x, local_sum);
                local_sum = __fmaf_rn(q_sh[d1 + 1], fk1.y, local_sum);
            }
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float k_val = __half2float(k_row[last]);
            local_sum = __fmaf_rn(q_last, k_val, local_sum);
        }
        // Block-wide reduction of local_sum to get sum across the block
        int lane = threadIdx.x & 31;
        int warpId = threadIdx.x >> 5;
        float warp_sum = warp_reduce_sum_f32(local_sum);
        if (lane == 0) {
            redbuf[warpId] = warp_sum;
        }
        __syncthreads();
        float alpha = 0.0f;
        float expv  = 0.0f;
        if (tid == 0) {
            float total = 0.0f;
            for (int w = 0; w < nwarps; ++w) {
                total += redbuf[w];
            }
            float s = total * scale;
            float m_prev = *mmem;
            float l_prev = *lmem;
            float m_new = fmaxf(m_prev, s);
            float a = __expf(m_prev - m_new);
            float e = __expf(s - m_new);
            float l_new = a * l_prev + e;
            *mmem = m_new;
            *lmem = l_new;
            scalars[0] = a;
            scalars[1] = e;
        }
        __syncthreads();
        alpha = scalars[0];
        expv  = scalars[1];
        // Update accumulators
        const __half* v_row = V + (bh_base_rows + (size_t)j) * (size_t)D;
        const __half2* vh2 = reinterpret_cast<const __half2*>(v_row);
        for (int i = tid; i < D2; i += nthreads * 2) {
            int i0 = i;
            int d0 = i0 * 2;
            float2 fv0 = __half22float2(vh2[i0]);
            float c0_0 = expv * fv0.x;
            float c0_1 = expv * fv0.y;
            acc_v_sh[d0]     = __fmaf_rn(alpha, acc_v_sh[d0],     c0_0);
            acc_v_sh[d0 + 1] = __fmaf_rn(alpha, acc_v_sh[d0 + 1], c0_1);
            int i1 = i0 + nthreads;
            if (i1 < D2) {
                int d1 = i1 * 2;
                float2 fv1 = __half22float2(vh2[i1]);
                float c1_0 = expv * fv1.x;
                float c1_1 = expv * fv1.y;
                acc_v_sh[d1]     = __fmaf_rn(alpha, acc_v_sh[d1],     c1_0);
                acc_v_sh[d1 + 1] = __fmaf_rn(alpha, acc_v_sh[d1 + 1], c1_1);
            }
        }
        if ((D & 1) && tid == 0) {
            int last = D - 1;
            float v_val = __half2float(v_row[last]);
            acc_last = __fmaf_rn(alpha, acc_last, expv * v_val);
        }
        __syncthreads();
    }
    // Normalize by l and write output
    float l_val = *lmem;
    float inv_l = 1.0f / l_val;
    __half2* out_h2 = reinterpret_cast<__half2*>(out_row);
    for (int i = tid; i < (D >> 1); i += nthreads * 2) {
        int i0 = i;
        int d0 = i0 * 2;
        float2 f0;
        f0.x = acc_v_sh[d0] * inv_l;
        f0.y = acc_v_sh[d0 + 1] * inv_l;
        out_h2[i0] = __floats2half2_rn(f0.x, f0.y);
        int i1 = i0 + nthreads;
        if (i1 < (D >> 1)) {
            int d1 = i1 * 2;
            float2 f1;
            f1.x = acc_v_sh[d1] * inv_l;
            f1.y = acc_v_sh[d1 + 1] * inv_l;
            out_h2[i1] = __floats2half2_rn(f1.x, f1.y);
        }
    }
    if ((D & 1) && tid == 0) {
        int last = D - 1;
        out_row[last] = __float2half_rn(acc_last * inv_l);
    }
}

torch::Tensor sdp_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda(), "Q must be a CUDA tensor");
    TORCH_CHECK(K.is_cuda(), "K must be a CUDA tensor");
    TORCH_CHECK(V.is_cuda(), "V must be a CUDA tensor");
    TORCH_CHECK(Q.scalar_type() == at::kHalf, "Q must be float16 (Half)");
    TORCH_CHECK(K.scalar_type() == at::kHalf, "K must be float16 (Half)");
    TORCH_CHECK(V.scalar_type() == at::kHalf, "V must be float16 (Half)");
    TORCH_CHECK(Q.sizes() == K.sizes(), "Q and K must have the same shape");
    TORCH_CHECK(Q.sizes() == V.sizes(), "Q and V must have the same shape");
    TORCH_CHECK(Q.dim() == 4, "Expected Q to have shape [B, H, S, D]");

    auto B = (int)Q.size(0);
    auto H = (int)Q.size(1);
    auto S = (int)Q.size(2);
    auto D = (int)Q.size(3);

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    auto Out = torch::empty_like(Qc);

    const __half* Qp = reinterpret_cast<const __half*>(Qc.data_ptr<at::Half>());
    const __half* Kp = reinterpret_cast<const __half*>(Kc.data_ptr<at::Half>());
    const __half* Vp = reinterpret_cast<const __half*>(Vc.data_ptr<at::Half>());
    __half* Outp = reinterpret_cast<__half*>(Out.data_ptr<at::Half>());

     dim3 grid((unsigned)S, (unsigned)H, (unsigned)B);
     int block = 128;
     int warps = (block + 31) / 32;
     size_t shmem = (size_t)D * sizeof(float)   // q_sh
                  + (size_t)D * sizeof(float)   // acc_v_sh
                  + (size_t)warps * sizeof(float) // redbuf
                  + (size_t)(4 * sizeof(float));  // scalars + l + m
     float scale = 1.0f / sqrtf((float)D);
    auto stream = at::cuda::getCurrentCUDAStream();
    sdp_fwd_kernel<<<grid, block, shmem, stream.stream()>>>(Qp, Kp, Vp, Outp, B, H, S, D, scale);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return Out;
}

